styles:
.grid { display: flex; flex-wrap: wrap; gap: 0.75rem; }

    .gallery {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
      gap: 0.75rem;
    }
    .gallery figure {
      margin: 0;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius, 0.5em);
      overflow: hidden;
      background: var(--is-bg-elev);
    }
    .gallery figcaption {
      padding: 0.55rem 0.75rem;
      font-size: 0.85em;
      color: var(--is-text-soft);
      border-top: 1px solid var(--is-border);
    }
    .gallery .lb-target {
      width: 100%;
      aspect-ratio: 16 / 9;
      display: grid;
      place-items: center;
      cursor: zoom-in;
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--is-text);
      background:
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--is-border) 40%, transparent) 0 8px,
          transparent 8px 16px),
        var(--is-bg);
    }
    .gallery .lb-target[data-tone="brand"] { background: var(--is-color-brand); color: #fff; }
    .gallery .lb-target[data-tone="success"] { background: #2f9e44; color: #fff; }
    .gallery .lb-target[data-tone="warning"] { background: #f08c00; color: #fff; }

    .video-card video { width: 100%; display: block; }

    pre.code { white-space: pre-wrap; }
